import { createInMemoryQueue, createQueueName, createFixedBackoff } from "@zudojs/queue";

async function drain(queue) {
  for (;;) {
    const job = await queue.claimNextJob();
    if (job !== null) {
      await queue.runJob(job);
      continue;
    }
    const stats = await queue.getStats();
    if (stats.retrying === 0 && stats.delayed === 0) return;
    await new Promise((resolve) => setTimeout(resolve, 5));
  }
}

const queue = createInMemoryQueue(createQueueName("emails"), {
  autoProcess: false,
  defaultJobOptions: { attempts: 3, backoff: createFixedBackoff(1) },
});
let failuresLeft = 1;
queue.process("send-email", async (job) => {
  if (failuresLeft-- > 0) throw new Error("SMTP 421");
  console.log(`sent to ${job.data.to}`);
});
await queue.add("send-email", { to: "bola@example.com" });
await drain(queue);
const stats = await queue.getStats();
console.log("succeeded:", stats.succeeded, "retried:", stats.retried);
await queue.close();

