class MemoryTaskRepository {
  rows = new Map();

  async create(input) {
    for (const row of this.rows.values()) {
      if (row.ownerId === input.ownerId && row.title === input.title) {
        throw new Error(`You already have a task called "${input.title}"`);
      }
    }
    const task = { ...input, id: this.rows.size + 1, status: "open" };
    this.rows.set(task.id, task);
    return task;
  }
}

