function failOnce(error, value) {
  const fn = async () => {
    fn.calls += 1;
    if (fn.calls === 1) throw error;
    return value;
  };
  fn.calls = 0;
  return fn;
}

const send = failOnce(new Error("SMTP 421"), "sent");
for (let attempt = 1; attempt <= 3; attempt++) {
  try {
    console.log(attempt, await send());
    break;
  } catch (error) {
    console.log(attempt, "failed:", error.message);
  }
}
console.log("calls:", send.calls);

